`timescale 1ns / 1ps
// sync_fifo: parameterizable single-clock FIFO with first-word fall-through.
// Interface: interface_spec.md. Implementation plan: microarchitecture.md.
// Occupancy is an explicit count register, so DEPTH need not be a power of two.
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                         clk,
    input  wire                         rst_n,
    input  wire                         wr_en,
    input  wire [WIDTH-1:0]             wr_data,
    output wire                         full,
    input  wire                         rd_en,
    output wire [WIDTH-1:0]             rd_data,
    output wire                         empty,
    output wire [$clog2(DEPTH+1)-1:0]   count
);

    // Widths.
    localparam integer PW = $clog2(DEPTH);       // pointer width (DEPTH >= 2)
    localparam integer CW = $clog2(DEPTH + 1);   // count width, holds DEPTH

    // Sized constants taken as part-selects of 32-bit values (width-clean).
    localparam [31:0]    LAST_V  = DEPTH - 1;
    localparam [31:0]    DEPTH_V = DEPTH;
    localparam [31:0]    ONE_V   = 1;
    localparam [PW-1:0]  LAST    = LAST_V[PW-1:0];
    localparam [PW-1:0]  PTR_ONE = ONE_V[PW-1:0];
    localparam [CW-1:0]  CNT_ONE = ONE_V[CW-1:0];
    localparam [CW-1:0]  DEPTH_C = DEPTH_V[CW-1:0];

    // Storage: datapath, not reset.
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    // State registers and their next values.
    reg [PW-1:0] wr_ptr;
    reg [PW-1:0] rd_ptr;
    reg [CW-1:0] count_q;
    reg [PW-1:0] wr_ptr_d;
    reg [PW-1:0] rd_ptr_d;
    reg [CW-1:0] count_d;

    // Flags are compares on the count register only.
    assign full    = (count_q == DEPTH_C);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;

    // First-word fall-through read of the oldest entry.
    assign rd_data = mem[rd_ptr];

    // Accepted requests: the flags gate the requests (overflow/underflow policy).
    wire wr_acc = wr_en & ~full;
    wire rd_acc = rd_en & ~empty;

    // Next-state logic.
    always @* begin
        wr_ptr_d = wr_ptr;
        rd_ptr_d = rd_ptr;
        count_d  = count_q;
        if (wr_acc) begin
            wr_ptr_d = (wr_ptr == LAST) ? {PW{1'b0}} : (wr_ptr + PTR_ONE);
        end
        if (rd_acc) begin
            rd_ptr_d = (rd_ptr == LAST) ? {PW{1'b0}} : (rd_ptr + PTR_ONE);
        end
        if (wr_acc && !rd_acc) begin
            count_d = count_q + CNT_ONE;
        end else if (rd_acc && !wr_acc) begin
            count_d = count_q - CNT_ONE;
        end
    end

    // Control registers: synchronous, active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= {PW{1'b0}};
            rd_ptr  <= {PW{1'b0}};
            count_q <= {CW{1'b0}};
        end else begin
            wr_ptr  <= wr_ptr_d;
            rd_ptr  <= rd_ptr_d;
            count_q <= count_d;
        end
    end

    // Storage write: only outside reset, only on an accepted write.
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr] <= wr_data;
        end
    end

`ifdef FORMAL
    // Design-intent assertions (not proven in this task).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    reg [CW:0] f_sum;
    always @(*) begin
        f_sum = {{(CW + 1 - PW){1'b0}}, rd_ptr} + {1'b0, count_q};
        if (f_sum >= DEPTH) f_sum = f_sum - DEPTH;
    end

    always @(*) begin
        if (f_past_valid) begin
            assert (!(full && empty));
            assert (count_q <= DEPTH_C);
            assert (wr_ptr <= LAST);
            assert (rd_ptr <= LAST);
            assert (wr_ptr == f_sum[PW-1:0]);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (count_q == {CW{1'b0}});
                assert (wr_ptr == {PW{1'b0}});
                assert (rd_ptr == {PW{1'b0}});
            end else begin
                if ($past(wr_acc) && !$past(rd_acc))
                    assert (count_q == $past(count_q) + CNT_ONE);
                if ($past(rd_acc) && !$past(wr_acc))
                    assert (count_q == $past(count_q) - CNT_ONE);
                if ($past(wr_acc) == $past(rd_acc))
                    assert (count_q == $past(count_q));
                if ($past(wr_en) && $past(full))
                    assert (wr_ptr == $past(wr_ptr));
                if ($past(rd_en) && $past(empty))
                    assert (rd_ptr == $past(rd_ptr));
            end
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) cover (full);
    end
`endif

endmodule
=== END FILE ===
