`timescale 1ns / 1ps
// Self-checking testbench for sync_fifo.
// Two DUTs on the same stimulus: DEPTH 8 x WIDTH 8 and DEPTH 5 x WIDTH 12.
// Each has a reference queue checked every cycle; coverage goals fail the run
// if not reached. Verdict line printed once before $finish.
module sync_fifo_tb;

    reg         clk;
    reg         rst_n;
    reg         wr_en;
    reg         rd_en;
    reg  [11:0] wr_data;

    wire        full8;
    wire        empty8;
    wire [7:0]  rd_data8;
    wire [3:0]  count8;

    wire        full5;
    wire        empty5;
    wire [11:0] rd_data5;
    wire [2:0]  count5;

    sync_fifo #(.DEPTH(8), .WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data[7:0]),
        .full    (full8),
        .rd_en   (rd_en),
        .rd_data (rd_data8),
        .empty   (empty8),
        .count   (count8)
    );

    sync_fifo #(.DEPTH(5), .WIDTH(12)) dut5 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .full    (full5),
        .rd_en   (rd_en),
        .rd_data (rd_data5),
        .empty   (empty5),
        .count   (count5)
    );

    // Reference model, DEPTH 8.
    reg [7:0]  m8 [0:7];
    reg [2:0]  h8;
    reg [2:0]  t8;
    reg [3:0]  c8;
    reg        aw8;
    reg        ar8;
    reg        was_full8;

    // Reference model, DEPTH 5.
    reg [11:0] m5 [0:4];
    reg [2:0]  h5;
    reg [2:0]  t5;
    reg [2:0]  c5;
    reg        aw5;
    reg        ar5;
    reg        was_full5;

    integer passed;
    integer failed;
    integer cyc;
    integer i;
    integer found;

    // Coverage counters.
    integer cv8_full, cv8_wfull, cv8_drain, cv8_rempty, cv8_bempty;
    integer cv8_bfull, cv8_bmid, cv8_wwrap, cv8_rwrap, cv8_rst;
    integer cv5_full, cv5_wfull, cv5_drain, cv5_rempty, cv5_bempty;
    integer cv5_bfull, cv5_bmid, cv5_wwrap, cv5_rwrap, cv5_rst;

    reg [31:0]      rng;
    reg [11:0]      dval;
    reg [8*64-1:0]  nonce;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task next_rand;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task check8;
        begin
            if (full8 !== (c8 == 4'd8)) begin
                failed = failed + 1;
                $error("D8 cycle %0d: full=%b expected %b", cyc, full8, (c8 == 4'd8));
            end else passed = passed + 1;
            if (empty8 !== (c8 == 4'd0)) begin
                failed = failed + 1;
                $error("D8 cycle %0d: empty=%b expected %b", cyc, empty8, (c8 == 4'd0));
            end else passed = passed + 1;
            if (count8 !== c8) begin
                failed = failed + 1;
                $error("D8 cycle %0d: count=%0d expected %0d", cyc, count8, c8);
            end else passed = passed + 1;
            if (c8 != 4'd0) begin
                if (rd_data8 !== m8[h8]) begin
                    failed = failed + 1;
                    $error("D8 cycle %0d: rd_data=%h expected %h", cyc, rd_data8, m8[h8]);
                end else passed = passed + 1;
            end
        end
    endtask

    task check5;
        begin
            if (full5 !== (c5 == 3'd5)) begin
                failed = failed + 1;
                $error("D5 cycle %0d: full=%b expected %b", cyc, full5, (c5 == 3'd5));
            end else passed = passed + 1;
            if (empty5 !== (c5 == 3'd0)) begin
                failed = failed + 1;
                $error("D5 cycle %0d: empty=%b expected %b", cyc, empty5, (c5 == 3'd0));
            end else passed = passed + 1;
            if (count5 !== c5) begin
                failed = failed + 1;
                $error("D5 cycle %0d: count=%0d expected %0d", cyc, count5, c5);
            end else passed = passed + 1;
            if (c5 != 3'd0) begin
                if (rd_data5 !== m5[h5]) begin
                    failed = failed + 1;
                    $error("D5 cycle %0d: rd_data=%h expected %h", cyc, rd_data5, m5[h5]);
                end else passed = passed + 1;
            end
        end
    endtask

    task cover8;
        begin
            if (rst_n) begin
                if (c8 == 4'd8) begin
                    cv8_full = cv8_full + 1;
                    was_full8 = 1'b1;
                end
                if ((c8 == 4'd0) && was_full8) begin
                    cv8_drain = cv8_drain + 1;
                    was_full8 = 1'b0;
                end
                if (wr_en && (c8 == 4'd8)) cv8_wfull = cv8_wfull + 1;
                if (rd_en && (c8 == 4'd0)) cv8_rempty = cv8_rempty + 1;
                if (wr_en && rd_en && (c8 == 4'd0)) cv8_bempty = cv8_bempty + 1;
                if (wr_en && rd_en && (c8 == 4'd8)) cv8_bfull = cv8_bfull + 1;
                if (wr_en && rd_en && (c8 != 4'd0) && (c8 != 4'd8)) cv8_bmid = cv8_bmid + 1;
                if (wr_en && (c8 != 4'd8) && (t8 == 3'd7)) cv8_wwrap = cv8_wwrap + 1;
                if (rd_en && (c8 != 4'd0) && (h8 == 3'd7)) cv8_rwrap = cv8_rwrap + 1;
            end else begin
                if (c8 != 4'd0) cv8_rst = cv8_rst + 1;
                was_full8 = 1'b0;
            end
        end
    endtask

    task cover5;
        begin
            if (rst_n) begin
                if (c5 == 3'd5) begin
                    cv5_full = cv5_full + 1;
                    was_full5 = 1'b1;
                end
                if ((c5 == 3'd0) && was_full5) begin
                    cv5_drain = cv5_drain + 1;
                    was_full5 = 1'b0;
                end
                if (wr_en && (c5 == 3'd5)) cv5_wfull = cv5_wfull + 1;
                if (rd_en && (c5 == 3'd0)) cv5_rempty = cv5_rempty + 1;
                if (wr_en && rd_en && (c5 == 3'd0)) cv5_bempty = cv5_bempty + 1;
                if (wr_en && rd_en && (c5 == 3'd5)) cv5_bfull = cv5_bfull + 1;
                if (wr_en && rd_en && (c5 != 3'd0) && (c5 != 3'd5)) cv5_bmid = cv5_bmid + 1;
                if (wr_en && (c5 != 3'd5) && (t5 == 3'd4)) cv5_wwrap = cv5_wwrap + 1;
                if (rd_en && (c5 != 3'd0) && (h5 == 3'd4)) cv5_rwrap = cv5_rwrap + 1;
            end else begin
                if (c5 != 3'd0) cv5_rst = cv5_rst + 1;
                was_full5 = 1'b0;
            end
        end
    endtask

    task update8;
        begin
            if (!rst_n) begin
                h8 = 3'd0;
                t8 = 3'd0;
                c8 = 4'd0;
            end else begin
                if (aw8) begin
                    m8[t8] = wr_data[7:0];
                    t8 = (t8 == 3'd7) ? 3'd0 : (t8 + 3'd1);
                end
                if (ar8) begin
                    h8 = (h8 == 3'd7) ? 3'd0 : (h8 + 3'd1);
                end
                if (aw8 && !ar8) c8 = c8 + 4'd1;
                else if (ar8 && !aw8) c8 = c8 - 4'd1;
            end
        end
    endtask

    task update5;
        begin
            if (!rst_n) begin
                h5 = 3'd0;
                t5 = 3'd0;
                c5 = 3'd0;
            end else begin
                if (aw5) begin
                    m5[t5] = wr_data;
                    t5 = (t5 == 3'd4) ? 3'd0 : (t5 + 3'd1);
                end
                if (ar5) begin
                    h5 = (h5 == 3'd4) ? 3'd0 : (h5 + 3'd1);
                end
                if (aw5 && !ar5) c5 = c5 + 3'd1;
                else if (ar5 && !aw5) c5 = c5 - 3'd1;
            end
        end
    endtask

    // One cycle: inputs were set at the preceding negedge. Check outputs
    // (state after the last rising edge), record coverage, advance one edge.
    task tick;
        begin
            cyc = cyc + 1;
            check8;
            check5;
            cover8;
            cover5;
            aw8 = rst_n && wr_en && (c8 != 4'd8);
            ar8 = rst_n && rd_en && (c8 != 4'd0);
            aw5 = rst_n && wr_en && (c5 != 3'd5);
            ar5 = rst_n && rd_en && (c5 != 3'd0);
            @(posedge clk);
            update8;
            update5;
            @(negedge clk);
        end
    endtask

    task rand_phase;
        input [7:0] w;
        input [7:0] r;
        input integer n;
        integer k;
        begin
            for (k = 0; k < n; k = k + 1) begin
                next_rand;
                wr_en = (rng[7:0] < w);
                rd_en = (rng[15:8] < r);
                next_rand;
                wr_data = rng[11:0];
                rst_n = (rng[31:24] != 8'hFF);
                tick;
            end
        end
    endtask

    // Coverage goal ids: 1 full, 2 write while full, 3 full then drained to
    // empty, 4 read while empty, 5 write+read when empty, 6 write+read when
    // full, 7 write+read in between, 8 write pointer wrap, 9 read pointer
    // wrap, 10 reset while holding entries. DEPTH 8 ids add 0, DEPTH 5 add 100.
    task cov_check;
        input integer v;
        input integer id;
        begin
            if (v == 0) begin
                failed = failed + 1;
                $error("coverage goal %0d not reached", id);
            end else passed = passed + 1;
        end
    endtask

    initial begin
        passed = 0;
        failed = 0;
        cyc    = 0;
        found  = 0;
        nonce  = {512{1'b0}};
        rng    = 32'h1234_5678;
        dval   = 12'h100;

        cv8_full = 0; cv8_wfull = 0; cv8_drain = 0; cv8_rempty = 0; cv8_bempty = 0;
        cv8_bfull = 0; cv8_bmid = 0; cv8_wwrap = 0; cv8_rwrap = 0; cv8_rst = 0;
        cv5_full = 0; cv5_wfull = 0; cv5_drain = 0; cv5_rempty = 0; cv5_bempty = 0;
        cv5_bfull = 0; cv5_bmid = 0; cv5_wwrap = 0; cv5_rwrap = 0; cv5_rst = 0;

        h8 = 3'd0; t8 = 3'd0; c8 = 4'd0; aw8 = 1'b0; ar8 = 1'b0; was_full8 = 1'b0;
        h5 = 3'd0; t5 = 3'd0; c5 = 3'd0; aw5 = 1'b0; ar5 = 1'b0; was_full5 = 1'b0;

        // Initial reset edge, with requests that must be ignored.
        rst_n   = 1'b0;
        wr_en   = 1'b1;
        rd_en   = 1'b1;
        wr_data = 12'h0A5;
        @(posedge clk);
        update8;
        update5;
        @(negedge clk);

        // Further reset cycles with requests active.
        tick;
        tick;

        // Out of reset, idle: must be empty.
        rst_n = 1'b1; wr_en = 1'b0; rd_en = 1'b0;
        tick;

        // Read while empty.
        rd_en = 1'b1;
        tick;

        // Write and read together when empty: only the write is accepted.
        wr_en = 1'b1; rd_en = 1'b1; wr_data = 12'h123;
        tick;

        // Fill to full and keep writing (writes while full are dropped).
        rd_en = 1'b0; wr_en = 1'b1;
        for (i = 0; i < 10; i = i + 1) begin
            wr_data = dval;
            dval = dval + 12'd1;
            tick;
        end

        // Write and read together when full, then in between.
        wr_en = 1'b1; rd_en = 1'b1;
        for (i = 0; i < 3; i = i + 1) begin
            wr_data = dval;
            dval = dval + 12'd1;
            tick;
        end

        // Drain to empty and keep reading (reads while empty are ignored).
        wr_en = 1'b0; rd_en = 1'b1;
        for (i = 0; i < 12; i = i + 1) begin
            tick;
        end

        // Reset during traffic: hold entries, then reset with requests active.
        wr_en = 1'b1; rd_en = 1'b0;
        for (i = 0; i < 4; i = i + 1) begin
            wr_data = dval;
            dval = dval + 12'd1;
            tick;
        end
        rst_n = 1'b0; wr_en = 1'b1; rd_en = 1'b1;
        tick;
        tick;
        rst_n = 1'b1; wr_en = 1'b0; rd_en = 1'b0;
        tick;

        // Random phases with different write/read rates and rare resets.
        rand_phase(8'd200, 8'd60,  400);
        rand_phase(8'd60,  8'd200, 400);
        rand_phase(8'd128, 8'd128, 400);
        rand_phase(8'd230, 8'd230, 400);
        rand_phase(8'd250, 8'd30,  400);
        rand_phase(8'd20,  8'd250, 400);

        // Coverage goals.
        cov_check(cv8_full,   1);
        cov_check(cv8_wfull,  2);
        cov_check(cv8_drain,  3);
        cov_check(cv8_rempty, 4);
        cov_check(cv8_bempty, 5);
        cov_check(cv8_bfull,  6);
        cov_check(cv8_bmid,   7);
        cov_check(cv8_wwrap,  8);
        cov_check(cv8_rwrap,  9);
        cov_check(cv8_rst,    10);
        cov_check(cv5_full,   101);
        cov_check(cv5_wfull,  102);
        cov_check(cv5_drain,  103);
        cov_check(cv5_rempty, 104);
        cov_check(cv5_bempty, 105);
        cov_check(cv5_bfull,  106);
        cov_check(cv5_bmid,   107);
        cov_check(cv5_wwrap,  108);
